import{_ as t,o as a,c as s,a4 as i}from"./chunks/framework.DpieW3qv.js";const p=JSON.parse('{"title":"status","description":"","frontmatter":{},"headers":[],"relativePath":"cli/status.md","filePath":"cli/status.md","lastUpdated":null}'),o={name:"cli/status.md"};function r(n,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;status&quot;">​</a></h1><p>Unified refresh dashboard for the active brand. Shows a short, focused list and lets you pick a refresh and run an action. Refresh labels include the go-live time from the campaign (e.g. <strong>r1 - 3pm</strong>, <strong>r2 - 3am</strong>).</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # Last 14 days + future; in TTY: summary + picker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Show full list (no date window)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="date-window" tabindex="-1">Date window <a class="header-anchor" href="#date-window" aria-label="Permalink to &quot;Date window&quot;">​</a></h2><p>By default only refreshes from the <strong>last 14 days</strong> through <strong>all future</strong> dates are shown, so you don’t scroll through a long list of past dates. Use <code>make status ALL=1</code> to see every refresh.</p><h2 id="interactive-terminal-tty" tabindex="-1">Interactive terminal (TTY) <a class="header-anchor" href="#interactive-terminal-tty" aria-label="Permalink to &quot;Interactive terminal (TTY)&quot;">​</a></h2><p>When you run <code>make status</code> in a normal terminal:</p><ol><li><strong>Legend</strong> — <code>LIVE = on site now · SYNCED = pushed · READY = ready to push · BUILD = needs build</code></li><li><strong>Summary line</strong> — e.g. <code>17 refreshes · 1 live · 2 synced · 1 ready · 13 to build</code></li><li><strong>Picker</strong> — one list of refreshes (↑↓ to move, Enter to select). Each row shows date, refresh label with time (e.g. <code>r1 - 3pm</code>), name, and status. Your active refresh is marked <strong>← active</strong>.</li><li><strong>Action</strong> — after choosing a refresh, choose: Set as active, Build, Rebuild (force), Preview, Push, Generate email, or Commit.</li></ol><p>The list appears only once (in the picker), not as a table and then again in the picker.</p><h2 id="non-interactive-e-g-make-pull" tabindex="-1">Non-interactive (e.g. make pull) <a class="header-anchor" href="#non-interactive-e-g-make-pull" aria-label="Permalink to &quot;Non-interactive (e.g. make pull)&quot;">​</a></h2><p>When status is run without a TTY (e.g. as part of <code>make pull</code>), it shows the full table: Date, Name, Status, Next Step, plus registry summary and footer. The Next Step column shows go-live time when relevant (e.g. <code>→ live 2/12 12 AM</code>).</p><h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Condition</th></tr></thead><tbody><tr><td><code>LIVE</code></td><td>Synced and date is today (currently live on site)</td></tr><tr><td><code>SYNCED</code></td><td>Synced and date is not today (ready for future go-live)</td></tr><tr><td><code>READY</code></td><td><code>ocapi-payload.json</code> exists, not yet pushed</td></tr><tr><td><code>BUILD</code></td><td><code>refresh.json</code> exists but no payload</td></tr></tbody></table><p>Status uses <strong>local</strong> sync state first (from <code>sync-config.json</code> in each refresh folder). When <strong>OCAPI is enabled</strong>, it also checks SFCC: if a refresh’s campaign exists on the site, that row is shown as SYNCED or LIVE even when local state is missing (e.g. after deleting dev-env). Any state learned from SFCC is <strong>written back to local</strong> automatically, so the next run (or build guards) can use it without re-querying SFCC.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/cli/pull.html">pull</a></li><li><a href="/ocapi-docs.github.io/cli/select.html">select</a></li><li><a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer workflow</a></li></ul>`,17)])])}const g=t(o,[["render",r]]);export{p as __pageData,g as default};
